    .{ .kind = .numeric, .numerator = 1000000000000, .denominator = 1 },
    .{ .kind = .numeric, .numerator = 10000000, .denominator = 1 },
    .{ .kind = .numeric, .numerator = 20000000, .denominator = 1 },
};

pub const table_bytes: usize = @sizeOf(@TypeOf(stage1)) + @sizeOf(@TypeOf(stage2)) + @sizeOf(@TypeOf(stage3)) + @sizeOf(@TypeOf(values));

pub fn numeric(cp: u21) ?Numeric {
    if (cp > 0x10ffff) return null;
    const mid = stage1[cp >> s1];
    const leaf = stage2[(@as(usize, mid) << (s1 - s2)) | (cp >> s2 & ((1 << (s1 - s2)) - 1))];
    const id = stage3[(@as(usize, leaf) << s2) | (cp & ((1 << s2) - 1))];
    return if (id == 0) null else values[id - 1];
}
